import{c as t,Q as a,j as r,m as o}from"./chunks/framework.BqPkuuVc.js";const p=JSON.parse('{"title":"Multi-operator setup","description":"","frontmatter":{},"headers":[],"relativePath":"user/reference/multi-operator-setup.md","filePath":"user/reference/multi-operator-setup.md"}'),n={name:"user/reference/multi-operator-setup.md"};function s(i,e,l,h,d,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="multi-operator-setup" tabindex="-1">Multi-operator setup <a class="header-anchor" href="#multi-operator-setup" aria-label="Permalink to &quot;Multi-operator setup&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers setting up the network and volunteer workstations at the event venue.</p><p>The practical details of running Manager with multiple people on multiple devices at the same event — network configuration, firewall settings, and what each workstation needs.</p><blockquote><p><strong>Status:</strong> Mostly stub — not yet written, apart from the addressing section below. For the conceptual overview of <em>why</em> Manager works this way, see <a href="./../what-is-mesho-manager/">How meshO Manager works</a>.</p></blockquote><h2 id="which-address-each-workstation-uses" tabindex="-1">Which address each workstation uses <a class="header-anchor" href="#which-address-each-workstation-uses" aria-label="Permalink to &quot;Which address each workstation uses&quot;">​</a></h2><p>The one part of this page that&#39;s written, because it catches people out every time.</p><p><strong>Settings → Server</strong> offers each app under two kinds of address — the computer&#39;s <strong>name</strong> and its <strong>LAN IP</strong>. Which one a workstation should use depends on what that workstation is:</p><ul><li><strong>Admin laptops</strong> — card download, station backup, the entry desk — should use the <strong>IP</strong> links. These machines need a browser with Web Serial (Chrome, Edge or Firefox 151+) to read a SportIdent reader, and in practice that means Chrome, which frequently can&#39;t resolve the computer&#39;s name.</li><li><strong>Phones, tablets and spectator TVs</strong> should use the <strong>name</strong> links. Mobile operating systems resolve the name automatically, and a name survives the server&#39;s IP changing.</li></ul><p>If you&#39;d rather give every machine a name, add a DHCP reservation with a host name on the venue router — that name is served by ordinary DNS, so every browser resolves it.</p><p>Full detail, including the exact Chrome error and how to set the router up: <strong><a href="./server-addresses">Reaching the server: name or IP</a></strong>.</p><h2 id="what-this-page-will-cover" tabindex="-1">What this page will cover <a class="header-anchor" href="#what-this-page-will-cover" aria-label="Permalink to &quot;What this page will cover&quot;">​</a></h2><h3 id="network-setup" tabindex="-1">Network setup <a class="header-anchor" href="#network-setup" aria-label="Permalink to &quot;Network setup&quot;">​</a></h3><ul><li>[ ] What kind of network you need at the venue (Wi-Fi router, ethernet switch, or both)</li><li>[ ] Internet access: not required, but useful for Eventor integration</li><li>[ ] Recommended network topology for a typical event (server on ethernet, volunteers on Wi-Fi)</li><li>[ ] IP addressing — fixed IP for the server, DHCP for clients</li></ul><h3 id="server-configuration" tabindex="-1">Server configuration <a class="header-anchor" href="#server-configuration" aria-label="Permalink to &quot;Server configuration&quot;">​</a></h3><ul><li>[x] Which port Manager listens on and how to find the URL to share with volunteers — see <a href="./server-addresses">Reaching the server: name or IP</a></li><li>[ ] Firewall rules on the server PC (Windows Firewall, etc.)</li><li>[x] What to do if volunteers can&#39;t reach the server — see <a href="./server-addresses#troubleshooting">Reaching the server: name or IP</a></li></ul><h3 id="connecting-workstations" tabindex="-1">Connecting workstations <a class="header-anchor" href="#connecting-workstations" aria-label="Permalink to &quot;Connecting workstations&quot;">​</a></h3><ul><li>[ ] What volunteers need: just a web browser — no install, no login</li><li>[ ] Supported browsers and minimum versions</li><li>[ ] Tablets and phones — what works well and what doesn&#39;t</li><li>[ ] Bookmarking the Manager URL for quick access</li></ul><h3 id="at-the-event" tabindex="-1">At the event <a class="header-anchor" href="#at-the-event" aria-label="Permalink to &quot;At the event&quot;">​</a></h3><ul><li>[ ] Recommended role split: who does what on which device</li><li>[ ] What happens when two people edit the same competitor at the same time</li><li>[ ] Performance: how many simultaneous clients Manager can handle</li><li>[ ] What happens when a client device loses Wi-Fi and reconnects</li></ul><h3 id="spectator-tvs" tabindex="-1">Spectator TVs <a class="header-anchor" href="#spectator-tvs" aria-label="Permalink to &quot;Spectator TVs&quot;">​</a></h3><ul><li>[ ] Setting up a TV as a display-only client</li><li>[ ] Kiosk mode / full-screen browser tips</li><li>[ ] Running displays on a separate network segment (if you want to isolate spectator traffic)</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../what-is-mesho-manager/">How meshO Manager works</a></li><li><a href="./../download-and-install/">Installing meshO Manager</a></li><li><a href="./server-addresses">Reaching the server: name or IP</a> — which link to hand each workstation, and why laptops running Chrome need the IP.</li><li><a href="./../running-the-event/splits-printing">Printing splits</a> — one printer at the server, or a printer at each download station.</li><li><a href="./https-and-certificates">HTTPS and certificates</a> — needed when a download/backup workstation is a different computer to the server.</li><li><a href="./../screens/creating-screens">Creating screens</a></li><li><a href="./../screens/tv-screens">TV screens</a></li><li><a href="./settings">Settings</a></li></ul>',23)])])}const w=t(n,[["render",s]]);export{p as __pageData,w as default};
